### **阶段三：体态识别引擎（Day 8-12）**

#### 步骤6：实现特征提取

```javascript
// src/core/feature-extractor.js

class FeatureExtractor {
  // 计算均值
  mean(arr) {
    return arr.reduce((a, b) => a + b, 0) / arr.length;
  }

  // 计算方差
  variance(arr) {
    const m = this.mean(arr);
    return arr.reduce((a, b) => a + Math.pow(b - m, 2), 0) / arr.length;
  }

  // 计算峰值
  peak(arr) {
    return Math.max(...arr.map(Math.abs));
  }

  // 从传感器数据提取12维特征
  extract(samples) {
    if (samples.length === 0) return null;

    const axArr = samples.map(s => s.ax);
    const ayArr = samples.map(s => s.ay);
    const azArr = samples.map(s => s.az);
    const gxArr = samples.map(s => s.gx);
    const gyArr = samples.map(s => s.gy);
    const gzArr = samples.map(s => s.gz);

    // 计算合加速度
    const totalAcc = samples.map(s => 
      Math.sqrt(s.ax * s.ax + s.ay * s.ay + s.az * s.az)
    );

    // 估算俯仰角（简化版：基于加速度分量）
    const pitchAngle = samples.map(s => 
      Math.atan2(s.ay, Math.sqrt(s.ax * s.ax + s.az * s.az)) * 180 / Math.PI
    );

    // 估算横滚角
    const rollAngle = samples.map(s =>
      Math.atan2(s.ax, s.az) * 180 / Math.PI
    );

    return {
      // 加速度特征
      accMeanX: this.mean(axArr),
      accMeanY: this.mean(ayArr),
      accMeanZ: this.mean(azArr),
      accVarX: this.variance(axArr),
      accVarY: this.variance(ayArr),
      accVarZ: this.variance(azArr),

      // 陀螺仪特征
      gyroMeanX: this.mean(gxArr),
      gyroMeanY: this.mean(gyArr),
      gyroMeanZ: this.mean(gzArr),

      // 合特征
      totalAccMean: this.mean(totalAcc),
      pitchMean: this.mean(pitchAngle),
      rollMean: this.mean(rollAngle),

      // 原始数据
      pitchAngle,
      rollAngle,
      totalAcc
    };
  }
}

export default new FeatureExtractor();
```

#### 步骤7：实现体态分类引擎

```javascript
// src/core/posture-engine.js
import { POSTURE_TYPES, SENSOR_CONFIG } from '../utils/constants';
import featureExtractor from './feature-extractor';
import dataCollector from './data-collector';

class PostureEngine {
  constructor() {
    this.currentType = POSTURE_TYPES.NORMAL;
    this.anomalyStartTime = null;
    this.lastReminderTime = 0;
    this.onPostureDetected = null;
  }

  // 主分类函数
  classify(features) {
    if (!features) return POSTURE_TYPES.NORMAL;

    // 规则1：低头前倾
    // 俯仰角 > 30° 且持续增大
    if (features.pitchMean > 30) {
      return {
        type: POSTURE_TYPES.HEAD_DOWN,
        confidence: Math.min(0.95, 0.8 + features.pitchMean / 100),
        reason: `俯仰角 ${features.pitchMean.toFixed(1)}°`
      };
    }

    // 规则2：久坐伏案
    // 合加速度接近1g（静止）+ 俯仰角 > 15°
    if (features.totalAccMean > 0.9 && features.totalAccMean < 1.1 && 
        features.pitchMean > 15 && features.accVarX < 0.01) {
      return {
        type: POSTURE_TYPES.SITTING_LONG,
        confidence: Math.min(0.9, 0.75 + features.pitchMean / 200),
        reason: `静止 + 俯仰角 ${features.pitchMean.toFixed(1)}°`
      };
    }

    // 规则3：跷二郎腿
    // Z轴陀螺仪周期性波动 + 横滚角波动
    if (features.gyroVarZ > 0.05 && features.rollMean > 15) {
      return {
        type: POSTURE_TYPES.CROSS_LEGS,
        confidence: Math.min(0.85, 0.7 + features.gyroVarZ),
        reason: `Z轴波动 ${features.gyroVarZ.toFixed(3)}`
      };
    }

    return {
      type: POSTURE_TYPES.NORMAL,
      confidence: 1.0,
      reason: '姿态正常'
    };
  }

  // 处理传感器样本
  processSample(sample) {
    const windowData = dataCollector.getWindowData();

    // 窗口数据不足时跳过
    if (windowData.length < SENSOR_CONFIG.WINDOW_SIZE) {
      return null;
    }

    // 提取特征
    const features = featureExtractor.extract(windowData);

    // 分类
    const result = this.classify(features);

    // 异常持续时间判断
    const now = Date.now();
    if (result.type !== POSTURE_TYPES.NORMAL) {
      if (this.currentType === result.type) {
        // 持续异常
        const duration = now - this.anomalyStartTime;

        // 持续时间超过阈值 且 冷却时间已过
        if (duration > SENSOR_CONFIG.MIN_DURATION && 
            now - this.lastReminderTime > SENSOR_CONFIG.REMINDER_COOLDOWN) {
          this.lastReminderTime = now;
          this.onPostureDetected && this.onPostureDetected(result, duration);
        }
      } else {
        // 新异常开始
        this.currentType = result.type;
        this.anomalyStartTime = now;
      }
    } else {
      // 恢复正常
      this.currentType = POSTURE_TYPES.NORMAL;
      this.anomalyStartTime = null;
    }

    return result;
  }

  // 重置状态
  reset() {
    this.currentType = POSTURE_TYPES.NORMAL;
    this.anomalyStartTime = null;
  }
}

export default new PostureEngine();
```

