### **阶段四：数据脱敏引擎（Day 13-14）**

#### 步骤8：实现脱敏引擎

```javascript
// src/core/desensitizer.js
import { DESENSITIZE_RULES } from '../utils/constants';

class Desensitizer {
  // 时间戳模糊化
  fuzzTimestamp(timestamp, granularity = 'hour') {
    const date = new Date(timestamp);

    switch (granularity) {
      case 'hour':
        date.setMinutes(0, 0, 0);
        break;
      case 'day':
        date.setHours(0, 0, 0, 0);
        break;
    }

    return date.toISOString();
  }

  // 心率区间归一化
  normalizeHeartRate(bpm, interval = 5) {
    const base = Math.floor(bpm / interval) * interval;
    return `${base}-${base + interval}`;
  }

  // GPS网格编码
  gridEncode(lat, lon, gridSize = 500) {
    // 简化版：将经纬度转换为网格编码
    const gridLat = Math.floor(lat * 1000 / gridSize);
    const gridLon = Math.floor(lon * 1000 / gridSize);

    // 生成网格ID
    const gridId = `Grid-${String.fromCharCode(65 + (gridLat % 26))}${gridLon % 100}`;

    return {
      gridId,
      gridSize,
      // 添加随机偏移，增强隐私
      offset: {
        lat: (Math.random() - 0.5) * gridSize / 111000,
        lon: (Math.random() - 0.5) * gridSize / 111000
      }
    };
  }

  // 步数聚合
  aggregateSteps(steps, interval = 100) {
    const base = Math.floor(steps / interval) * interval;
    return base;
  }

  // 处理心率数据
  processHeartRate(records) {
    return records.map(record => ({
      bpmRange: this.normalizeHeartRate(record.bpm),
      timestamp: this.fuzzTimestamp(record.timestamp),
      // 不保留精确BPM
    }));
  }

  // 处理轨迹数据
  processTrajectory(records) {
    return records.map(record => ({
      grid: this.gridEncode(record.lat, record.lon),
      timestamp: this.fuzzTimestamp(record.timestamp),
      // 不保留精确坐标
    }));
  }

  // 处理步数数据
  processStepData(records) {
    return records.map(record => ({
      steps: this.aggregateSteps(record.steps),
      timestamp: this.fuzzTimestamp(record.timestamp),
    }));
  }

  // 处理姿态数据（保留特征，用于体态分析）
  processPostureData(samples) {
    return samples.map(sample => ({
      ax: parseFloat(sample.ax.toFixed(2)),
      ay: parseFloat(sample.ay.toFixed(2)),
      az: parseFloat(sample.az.toFixed(2)),
      // 陀螺仪数据可选择保留或舍弃
      timestamp: this.fuzzTimestamp(sample.timestamp, 'day'),
    }));
  }

  // 通用脱敏处理
  process(data, type) {
    switch (type) {
      case 'heartRate':
        return this.processHeartRate(data);
      case 'trajectory':
        return this.processTrajectory(data);
      case 'steps':
        return this.processStepData(data);
      case 'posture':
        return this.processPostureData(data);
      default:
        return data;
    }
  }
}

export default new Desensitizer();
```

