### **阶段五：AES加密存储引擎（Day 15-19）**

#### 步骤9：实现AES加密引擎

```javascript
// src/core/crypto-engine.js
import { CRYPTO_CONFIG } from '../utils/constants';

// 简化版AES实现（实际项目中可使用crypto-js库）
class CryptoEngine {
  constructor() {
    this.keys = {};
  }

  // 密钥派生（基于设备UID）
  deriveKey(deviceUID, salt, level) {
    // 简化版：实际应使用HKDF/PBKDF2
    const baseStr = `${deviceUID}-${salt}-${level}`;
    let hash = 0;
    for (let i = 0; i < baseStr.length; i++) {
      const char = baseStr.charCodeAt(i);
      hash = ((hash << 5) - hash) + char;
      hash = hash & hash; // 转换为32位整数
    }

    // 生成16字节密钥
    const key = new Array(16);
    for (let i = 0; i < 16; i++) {
      key[i] = (hash >> (i % 4 * 8)) & 0xFF;
    }

    return key;
  }

  // 生成随机IV
  generateIV() {
    const iv = new Array(16);
    for (let i = 0; i < 16; i++) {
      iv[i] = Math.floor(Math.random() * 256);
    }
    return iv;
  }

  // PKCS#7填充
  pkcs7Pad(data, blockSize = 16) {
    const padLen = blockSize - (data.length % blockSize);
    return [...data, ...new Array(padLen).fill(padLen)];
  }

  // PKCS#7去填充
  pkcs7Unpad(data) {
    const padLen = data[data.length - 1];
    return data.slice(0, data.length - padLen);
  }

  // 简化版AES加密（实际项目应使用完整AES实现）
  encrypt(plaintext, key, iv) {
    // 这里使用简化的XOR加密作为演示
    // 实际项目中应使用完整的AES-128-CBC实现
    const data = new TextEncoder().encode(plaintext);
    const padded = this.pkcs7Pad(data);

    const ciphertext = new Array(padded.length);
    for (let i = 0; i < padded.length; i++) {
      ciphertext[i] = padded[i] ^ key[i % key.length] ^ iv[i % iv.length];
    }

    return ciphertext;
  }

  // 简化版AES解密
  decrypt(ciphertext, key, iv) {
    const decrypted = new Array(ciphertext.length);
    for (let i = 0; i < ciphertext.length; i++) {
      decrypted[i] = ciphertext[i] ^ key[i % key.length] ^ iv[i % iv.length];
    }

    const unpadded = this.pkcs7Unpad(decrypted);
    return new TextDecoder().decode(new Uint8Array(unpadded));
  }

  // 加密数据
  encryptData(data, level = 'L1') {
    const plaintext = JSON.stringify(data);
    const iv = this.generateIV();

    // 获取对应层级的密钥
    if (!this.keys[level]) {
      const salt = CRYPTO_CONFIG.LEVELS[level].name;
      this.keys[level] = this.deriveKey('device-uid-placeholder', salt, level);
    }

    const ciphertext = this.encrypt(plaintext, this.keys[level], iv);

    return {
      ciphertext,
      iv,
      level,
      timestamp: Date.now()
    };
  }

  // 解密数据
  decryptData(encryptedData) {
    const { ciphertext, iv, level } = encryptedData;

    if (!this.keys[level]) {
      throw new Error(`密钥未初始化: ${level}`);
    }

    const plaintext = this.decrypt(ciphertext, this.keys[level], iv);
    return JSON.parse(plaintext);
  }

  // 安全清零密钥
  clearKeys() {
    Object.keys(this.keys).forEach(key => {
      delete this.keys[key];
    });
  }
}

export default new CryptoEngine();
