#### 步骤10：实现存储管理器

```javascript
// src/core/storage-manager.js
import cryptoEngine from './crypto-engine';
import { CRYPTO_CONFIG } from '../utils/constants';

class StorageManager {
  constructor() {
    this.storageKey = 'posture-guard-data';
  }

  // 保存加密数据
  save(key, data, options = {}) {
    const { level = 'L1', expiryDays = CRYPTO_CONFIG.LEVELS.L1.retentionDays } = options;

    // 加密数据
    const encrypted = cryptoEngine.encryptData(data, level);

    // 添加元数据
    const record = {
      ...encrypted,
      createTime: Date.now(),
      expiryTime: Date.now() + expiryDays * 24 * 60 * 60 * 1000,
      key
    };

    // 读取现有数据
    const allData = this.getAll();
    allData[key] = record;

    // 保存到本地存储
    try {
      // 模拟存储（实际应使用系统文件API）
      localStorage.setItem(this.storageKey, JSON.stringify(allData));
      console.log(`数据已保存: ${key}`);
      return true;
    } catch (e) {
      console.error('存储失败:', e);
      return false;
    }
  }

  // 读取并解密数据
  load(key) {
    const allData = this.getAll();
    const record = allData[key];

    if (!record) {
      return { expired: false, data: null };
    }

    // 检查是否过期
    if (Date.now() > record.expiryTime) {
      return { expired: true, data: null };
    }

    try {
      const data = cryptoEngine.decryptData(record);
      return { expired: false, data };
    } catch (e) {
      console.error('解密失败:', e);
      return { expired: false, data: null };
    }
  }

  // 获取所有数据
  getAll() {
    try {
      const raw = localStorage.getItem(this.storageKey);
      return raw ? JSON.parse(raw) : {};
    } catch (e) {
      return {};
    }
  }

  // 删除指定数据
  delete(key) {
    const allData = this.getAll();
    delete allData[key];
    localStorage.setItem(this.storageKey, JSON.stringify(allData));
  }

  // 清理过期数据
  cleanup() {
    const allData = this.getAll();
    const now = Date.now();
    let cleanedCount = 0;

    Object.keys(allData).forEach(key => {
      if (now > allData[key].expiryTime) {
        delete allData[key];
        cleanedCount++;
      }
    });

    if (cleanedCount > 0) {
      localStorage.setItem(this.storageKey, JSON.stringify(allData));
      console.log(`已清理 ${cleanedCount} 条过期数据`);
    }

    return cleanedCount;
  }

  // 安全删除（覆写清零）
  secureDelete(key) {
    // 先用随机数据覆写
    const allData = this.getAll();
    if (allData[key]) {
      allData[key].ciphertext = new Array(1024).fill(0).map(() => 
        Math.floor(Math.random() * 256)
      );
      localStorage.setItem(this.storageKey, JSON.stringify(allData));
    }

    // 然后删除
    this.delete(key);
  }
}

export default new StorageManager();
