```javascript
// src/core/reminder-manager.js
import { POSTURE_TYPES, SENSOR_CONFIG } from '../utils/constants';

class ReminderManager {
  constructor() {
    this.lastReminderTime = 0;
    this.reminderHistory = [];
    this.onReminder = null;
  }

  // 检查冷却时间
  checkCooldown() {
    const now = Date.now();
    return now - this.lastReminderTime >= SENSOR_CONFIG.REMINDER_COOLDOWN;
  }

  // 获取提醒消息
  getReminderMessage(type, duration) {
    const messages = {
      [POSTURE_TYPES.HEAD_DOWN]: {
        title: '体态提醒',
        message: `检测到低头前倾姿态，已持续${Math.floor(duration / 60000)}分钟，请抬头活动颈椎`,
        icon: '⚠️'
      },
      [POSTURE_TYPES.SITTING_LONG]: {
        title: '久坐提醒',
        message: `检测到久坐伏案，已持续${Math.floor(duration / 60000)}分钟，请起身活动`,
        icon: '⏰'
      },
      [POSTURE_TYPES.CROSS_LEGS]: {
        title: '姿势提醒',
        message: `检测到跷二郎腿，已持续${Math.floor(duration / 60000)}分钟，请调整坐姿`,
        icon: '🪑'
      }
    };

    return messages[type] || { title: '提醒', message: '请注意姿势', icon: '💡' };
  }

  // 触发提醒
  trigger(type, duration) {
    if (!this.checkCooldown()) {
      console.log('冷却中，跳过提醒');
      return false;
    }

    const reminder = this.getReminderMessage(type, duration);

    // 记录提醒历史
    this.reminderHistory.unshift({
      type,
      message: reminder.message,
      timestamp: Date.now()
    });

    // 保留最近20条记录
    if (this.reminderHistory.length > 20) {
      this.reminderHistory.pop();
    }

    this.lastReminderTime = Date.now();

    // 触发回调（用于UI显示）
    this.onReminder && this.onReminder(reminder);

    // 触发震动（模拟）
    this.vibrate();

    console.log('提醒触发:', reminder);
    return true;
  }

  // 震动提醒
  vibrate() {
    try {
      // 模拟器环境下可能不支持
      // 实际应调用系统震动API
      console.log('震动: 200ms');
    } catch (e) {
      console.log('震动API不可用');
    }
  }

  // 获取提醒历史
  getHistory() {
    return [...this.reminderHistory];
  }

  // 清空历史
  clearHistory() {
    this.reminderHistory = [];
  }
}

export default new ReminderManager();
