// src/test/test-suite.js
import sensorMock from '../mock/sensor-mock';
import postureEngine from '../core/posture-engine';
import desensitizer from '../core/desensitizer';
import cryptoEngine from '../core/crypto-engine';
import storageManager from '../core/storage-manager';

class TestSuite {
  constructor() {
    this.results = [];
  }

  // 测试体态识别
  testPostureRecognition() {
    console.log('=== 测试体态识别 ===');

    const testCases = [
      { type: 'HEAD_DOWN', expected: 'HEAD_DOWN', duration: 15 * 60000 },
      { type: 'SITTING_LONG', expected: 'SITTING_LONG', duration: 45 * 60000 },
      { type: 'CROSS_LEGS', expected: 'CROSS_LEGS', duration: 5 * 60000 },
      { type: 'NORMAL', expected: 'NORMAL', duration: 5 * 60000 }
    ];

    testCases.forEach(testCase => {
      const data = sensorMock.generate(testCase.type, testCase.duration);
      // 模拟处理
      const result = postureEngine.classify(
        require('../core/feature-extractor').extract(data.slice(-100))
      );

      const passed = result.type === testCase.expected;
      this.results.push({
        test: `体态识别 - ${testCase.type}`,
        passed,
        expected: testCase.expected,
        actual: result.type
      });

      console.log(`${passed ? '✓' : '✗'} ${testCase.type}: ${result.type} (置信度: ${result.confidence})`);
    });
  }

  // 测试数据脱敏
  testDesensitization() {
    console.log('\n=== 测试数据脱敏 ===');

    // 测试时间戳脱敏
    const timestamp = new Date('2026-08-20T14:32:15').getTime();
    const fuzzed = desensitizer.fuzzTimestamp(timestamp);
    console.log(`时间戳脱敏: ${new Date(timestamp).toISOString()} → ${fuzzed}`);

    // 测试心率脱敏
    const hr = desensitizer.normalizeHeartRate(72);
    console.log(`心率脱敏: 72 BPM → ${hr}`);

    // 测试GPS脱敏
    const gps = desensitizer.gridEncode(39.916, 116.397);
    console.log(`GPS脱敏: (39.916, 116.397) → ${gps.gridId}`);
  }

  // 测试加密解密
  testEncryption() {
    console.log('\n=== 测试加密解密 ===');

    const testData = { heartRate: 72, timestamp: Date.now() };
    const encrypted = cryptoEngine.encryptData(testData, 'L1');
    console.log('加密成功:', encrypted.ciphertext.length > 0);

    const decrypted = cryptoEngine.decryptData(encrypted);
    console.log('解密成功:', JSON.stringify(decrypted));
    console.log('数据一致:', JSON.stringify(testData) === JSON.stringify(decrypted));
  }

  // 测试存储
  testStorage() {
    console.log('\n=== 测试存储管理 ===');

    const testData = { steps: 5000, heartRate: [65, 72, 78] };
    storageManager.save('test-data', testData, { level: 'L1', expiryDays: 1 });

    const loaded = storageManager.load('test-data');
    console.log('存储读取:', loaded.data !== null);

    storageManager.delete('test-data');
    const afterDelete = storageManager.load('test-data');
    console.log('删除验证:', afterDelete.data === null);
  }

  // 运行所有测试
  runAll() {
    console.log('开始运行测试套件...\n');

    this.testPostureRecognition();
    this.testDesensitization();
    this.testEncryption();
    this.testStorage();

    const passed = this.results.filter(r => r.passed).length;
    const total = this.results.length;

    console.log(`\n=== 测试结果 ===`);
    console.log(`通过: ${passed}/${total}`);

    return { passed, total, results: this.results };
  }
}

export default new TestSuite();
