/**
 * 常量定义文件
 * 体态守护 - OpenVela可穿戴快应用
 */

// 体态类型枚举
export const POSTURE_TYPES = {
  NORMAL: 'NORMAL',
  HEAD_DOWN: 'HEAD_DOWN',      // 低头前倾
  SITTING_LONG: 'SITTING_LONG', // 久坐伏案
  CROSS_LEGS: 'CROSS_LEGS'    // 跷二郎腿
};

// 体态类型中文名
export const POSTURE_NAMES = {
  [POSTURE_TYPES.NORMAL]: '正常',
  [POSTURE_TYPES.HEAD_DOWN]: '低头前倾',
  [POSTURE_TYPES.SITTING_LONG]: '久坐伏案',
  [POSTURE_TYPES.CROSS_LEGS]: '跷二郎腿'
};

// 传感器配置
export const SENSOR_CONFIG = {
  SAMPLE_RATE: 50,           // 50Hz采样
  WINDOW_SIZE: 100,          // 2秒窗口（50*2）
  MIN_DURATION: 600000,      // 10分钟最小持续时间
  REMINDER_COOLDOWN: 300000  // 5分钟提醒冷却
};

// 加密配置
export const CRYPTO_CONFIG = {
  ALGORITHM: 'AES-128-CBC',
  KEY_LENGTH: 16,
  IV_LENGTH: 16,
  LEVELS: {
    L1: { name: '普通数据', retentionDays: 30 },
    L2: { name: '隐私数据', retentionDays: 7 }
  }
};

// 脱敏规则配置
export const DESENSITIZE_RULES = {
  TIMESTAMP: { granularity: 'hour' },
  HEART_RATE: { interval: 5 },
  GPS: { gridSize: 500 }
};

// 提醒消息模板
export const REMINDER_MESSAGES = {
  [POSTURE_TYPES.HEAD_DOWN]: {
    title: '体态提醒',
    message: '检测到低头前倾姿态，请抬头活动颈椎',
    icon: '⚠️'
  },
  [POSTURE_TYPES.SITTING_LONG]: {
    title: '久坐提醒',
    message: '检测到久坐伏案，请起身活动',
    icon: '⏰'
  },
  [POSTURE_TYPES.CROSS_LEGS]: {
    title: '姿势提醒',
    message: '检测到跷二郎腿，请调整坐姿',
    icon: '🪑'
  }
};

// 页面路由
export const ROUTES = {
  INDEX: '/pages/index',
  POSTURE: '/pages/posture',
  SECURITY: '/pages/security',
  SETTINGS: '/pages/settings'
};

// 存储键名
export const STORAGE_KEYS = {
  POSTURE_STATS: 'postureStats',
  HEALTH_DATA: 'healthData',
  SECURITY_LOGS: 'securityLogs',
  SETTINGS: 'settings'
};

/**
 * Mock传感器数据生成器
 * 用于模拟器环境下模拟各类体态场景
 */

import { POSTURE_TYPES } from '../utils/constants';

class SensorMock {
  constructor() {
    this.scenarios = {
      [POSTURE_TYPES.HEAD_DOWN]: this.generateHeadDown.bind(this),
      [POSTURE_TYPES.SITTING_LONG]: this.generateSittingLong.bind(this),
      [POSTURE_TYPES.CROSS_LEGS]: this.generateCrossLegs.bind(this),
      [POSTURE_TYPES.NORMAL]: this.generateNormal.bind(this)
    };
  }

  /**
   * 生成低头前倾场景数据
   * 特征：俯仰角逐渐增大，ay分量逐渐减小
   */
  generateHeadDown(t) {
    const progress = Math.min(t / 600000, 1); // 10分钟内逐渐前倾
    return {
      ax: 0.2 + Math.sin(t * 0.001) * 0.05,
      ay: -0.3 - progress * 0.4,  // 俯仰角逐渐增大
      az: 0.8 + progress * 0.1,
      gx: 0,
      gy: 0.1 + progress * 0.2,
      gz: 0,
      timestamp: Date.now()
    };
  }

  /**
   * 生成久坐伏案场景数据
   * 特征：合加速度接近1g，俯仰角15-25度，方差小
   */
  generateSittingLong(t) {
    return {
      ax: 0.1 + Math.sin(t * 0.0005) * 0.02,
      ay: -0.2 + Math.sin(t * 0.001) * 0.05,
      az: 0.95,
      gx: 0,
      gy: 0.05,
      gz: 0,
      timestamp: Date.now()
    };
  }

  /**
   * 生成跷二郎腿场景数据
   * 特征：Z轴陀螺仪周期性波动，横滚角波动
   */
  generateCrossLegs(t) {
    return {
      ax: 0.3 + Math.sin(t * 0.003) * 0.2,
      ay: 0.1,
      az: 0.9,
      gx: 0,
      gy: 0,
      gz: Math.sin(t * 0.005) * 0.3,  // Z轴周期性波动
      timestamp: Date.now()
    };
  }

  /**
   * 生成正常姿态数据
   * 特征：各轴数据稳定，小幅随机波动
   */
  generateNormal(t) {
    return {
      ax: 0.1 + (Math.random() - 0.5) * 0.05,
      ay: 0.05 + (Math.random() - 0.5) * 0.03,
      az: 0.98 + (Math.random() - 0.5) * 0.02,
      gx: (Math.random() - 0.5) * 0.1,
      gy: (Math.random() - 0.5) * 0.1,
      gz: (Math.random() - 0.5) * 0.1,
      timestamp: Date.now()
    };
  }

  /**
   * 根据场景类型生成单个样本
   */
  generateSample(type) {
    const generator = this.scenarios[type] || this.scenarios[POSTURE_TYPES.NORMAL];
    return generator(Math.random() * 10000);
  }

  /**
   * 根据场景类型生成一段时间的数据
   */
  generate(type, duration = 1000) {
    const generator = this.scenarios[type] || this.scenarios[POSTURE_TYPES.NORMAL];
    const data = [];
    const startTime = Date.now();
    const sampleInterval = 1000 / 50; // 50Hz

    while (Date.now() - startTime < duration) {
      data.push(generator(Date.now() - startTime));
    }

    return data;
  }

  /**
   * 生成心率数据
   */
  generateHeartRate(duration = 3600000) {
    const data = [];
    const startTime = Date.now();
    const interval = 60000; // 每分钟一个点

    for (let t = 0; t < duration; t += interval) {
      // 模拟心率变化：静息60-80，活动时90-120
      const baseRate = 65 + Math.sin(t / 600000) * 15;
      const noise = (Math.random() - 0.5) * 10;
      data.push({
        bpm: Math.round(baseRate + noise),
        timestamp: startTime + t
      });
    }

    return data;
  }

  /**
   * 生成步数数据
   */
  generateSteps(duration = 3600000) {
    const data = [];
    const startTime = Date.now();
    const interval = 300000; // 每5分钟一个点

    let totalSteps = 0;
    for (let t = 0; t < duration; t += interval) {
      // 模拟步行：每5分钟100-300步
      const steps = Math.floor(100 + Math.random() * 200);
      totalSteps += steps;
      data.push({
        steps: totalSteps,
        timestamp: startTime + t
      });
    }

    return data;
  }

  /**
   * 生成GPS轨迹数据
   */
  generateTrajectory(duration = 3600000) {
    const data = [];
    const startTime = Date.now();
    const interval = 60000; // 每分钟一个点

    // 起始位置：北京天安门附近
    let lat = 39.916;
    let lon = 116.397;

    for (let t = 0; t < duration; t += interval) {
      // 模拟移动：小幅随机偏移
      lat += (Math.random() - 0.5) * 0.001;
      lon += (Math.random() - 0.5) * 0.001;

      data.push({
        lat: parseFloat(lat.toFixed(6)),
        lon: parseFloat(lon.toFixed(6)),
        timestamp: startTime + t
      });
    }

    return data;
  }
}

export default new SensorMock();

/**
 * 特征提取器
 * 从传感器时序数据中提取12维特征向量
 */

class FeatureExtractor {
  /**
   * 计算数组均值
   */
  mean(arr) {
    if (!arr || arr.length === 0) return 0;
    return arr.reduce((a, b) => a + b, 0) / arr.length;
  }

  /**
   * 计算数组方差
   */
  variance(arr) {
    if (!arr || arr.length === 0) return 0;
    const m = this.mean(arr);
    return arr.reduce((a, b) => a + Math.pow(b - m, 2), 0) / arr.length;
  }

  /**
   * 计算数组标准差
   */
  std(arr) {
    return Math.sqrt(this.variance(arr));
  }

  /**
   * 计算峰值（最大绝对值）
   */
  peak(arr) {
    if (!arr || arr.length === 0) return 0;
    return Math.max(...arr.map(Math.abs));
  }

  /**
   * 计算均方根
   */
  rms(arr) {
    if (!arr || arr.length === 0) return 0;
    const sumSquares = arr.reduce((a, b) => a + b * b, 0);
    return Math.sqrt(sumSquares / arr.length);
  }

  /**
   * 计算过零率
   */
  zeroCrossingRate(arr) {
    if (!arr || arr.length < 2) return 0;
    let count = 0;
    for (let i = 1; i < arr.length; i++) {
      if ((arr[i] >= 0 && arr[i - 1] < 0) || (arr[i] < 0 && arr[i - 1] >= 0)) {
        count++;
      }
    }
    return count / (arr.length - 1);
  }

  /**
   * 从传感器数据提取12维特征
   * @param {Array} samples - 传感器样本数组
   * @returns {Object} 特征向量
   */
  extract(samples) {
    if (!samples || samples.length === 0) {
      return this.getEmptyFeatures();
    }

    const axArr = samples.map(s => s.ax);
    const ayArr = samples.map(s => s.ay);
    const azArr = samples.map(s => s.az);
    const gxArr = samples.map(s => s.gx);
    const gyArr = samples.map(s => s.gy);
    const gzArr = samples.map(s => s.gz);

    // 计算合加速度
    const totalAcc = samples.map(s =>
      Math.sqrt(s.ax * s.ax + s.ay * s.ay + s.az * s.az)
    );

    // 估算俯仰角（简化版：基于加速度分量）
    // 俯仰角 = atan2(ay, sqrt(ax^2 + az^2))
    const pitchAngle = samples.map(s =>
      Math.atan2(s.ay, Math.sqrt(s.ax * s.ax + s.az * s.az)) * 180 / Math.PI
    );

    // 估算横滚角
    // 横滚角 = atan2(ax, az)
    const rollAngle = samples.map(s =>
      Math.atan2(s.ax, s.az) * 180 / Math.PI
    );

    // 计算陀螺仪方差（用于检测跷二郎腿）
    const gyroVarZ = this.variance(gzArr);

    return {
      // 加速度特征（6维）
      accMeanX: this.mean(axArr),
      accMeanY: this.mean(ayArr),
      accMeanZ: this.mean(azArr),
      accVarX: this.variance(axArr),
      accVarY: this.variance(ayArr),
      accVarZ: this.variance(azArr),

      // 陀螺仪特征（3维）
      gyroMeanX: this.mean(gxArr),
      gyroMeanY: this.mean(gyArr),
      gyroMeanZ: this.mean(gzArr),

      // 合特征（3维）
      totalAccMean: this.mean(totalAcc),
      pitchMean: this.mean(pitchAngle),
      rollMean: this.mean(rollAngle),

      // 额外特征
      gyroVarZ: gyroVarZ,
      pitchStd: this.std(pitchAngle),
      rollStd: this.std(rollAngle),

      // 原始角度数组（用于可视化）
      pitchAngle,
      rollAngle,
      totalAcc
    };
  }

  /**
   * 获取空特征对象
   */
  getEmptyFeatures() {
    return {
      accMeanX: 0,
      accMeanY: 0,
      accMeanZ: 0,
      accVarX: 0,
      accVarY: 0,
      accVarZ: 0,
      gyroMeanX: 0,
      gyroMeanY: 0,
      gyroMeanZ: 0,
      totalAccMean: 0,
      pitchMean: 0,
      rollMean: 0,
      gyroVarZ: 0,
      pitchStd: 0,
      rollStd: 0,
      pitchAngle: [],
      rollAngle: [],
      totalAcc: []
    };
  }

  /**
   * 特征归一化（用于机器学习）
   */
  normalize(features, stats = null) {
    const keys = [
      'accMeanX', 'accMeanY', 'accMeanZ',
      'accVarX', 'accVarY', 'accVarZ',
      'gyroMeanX', 'gyroMeanY', 'gyroMeanZ',
      'totalAccMean', 'pitchMean', 'rollMean'
    ];

    // 默认统计值（基于经验值）
    const defaultStats = {
      accMeanX: { mean: 0.15, std: 0.3 },
      accMeanY: { mean: 0, std: 0.4 },
      accMeanZ: { mean: 0.95, std: 0.2 },
      accVarX: { mean: 0.01, std: 0.02 },
      accVarY: { mean: 0.01, std: 0.02 },
      accVarZ: { mean: 0.01, std: 0.02 },
      gyroMeanX: { mean: 0, std: 0.2 },
      gyroMeanY: { mean: 0, std: 0.2 },
      gyroMeanZ: { mean: 0, std: 0.2 },
      totalAccMean: { mean: 1.0, std: 0.2 },
      pitchMean: { mean: 0, std: 20 },
      rollMean: { mean: 0, std: 15 }
    };

    const s = stats || defaultStats;
    const normalized = {};

    for (const key of keys) {
      if (s[key] && s[key].std > 0) {
        normalized[key] = (features[key] - s[key].mean) / s[key].std;
      } else {
        normalized[key] = features[key];
      }
    }

    return normalized;
  }
}

export default new FeatureExtractor();

/**
 * 数据采集器
 * 负责传感器数据采集和滑动窗口管理
 */

import { SENSOR_CONFIG } from '../utils/constants';
import sensorMock from '../mock/sensor-mock';

class DataCollector {
  constructor() {
    this.buffer = [];
    this.isCollecting = false;
    this.sampleInterval = null;
    this.currentScenario = 'normal';
    this.onSample = null;
    this.onWindowReady = null;
    this.sampleCount = 0;
  }

  /**
   * 开始采集数据
   * @param {string} scenario - 场景类型（mock模式下使用）
   */
  start(scenario = 'normal') {
    if (this.isCollecting) {
      console.log('采集器已在运行中');
      return;
    }

    this.isCollecting = true;
    this.currentScenario = scenario;
    this.buffer = [];
    this.sampleCount = 0;

    console.log(`开始采集数据，场景: ${scenario}`);

    // 模拟器环境下使用Mock数据
    this.sampleInterval = setInterval(() => {
      const sample = sensorMock.generateSample(this.currentScenario);
      this.processSample(sample);
    }, 1000 / SENSOR_CONFIG.SAMPLE_RATE);
  }

  /**
   * 处理单个样本
   */
  processSample(sample) {
    this.buffer.push(sample);
    this.sampleCount++;

    // 维护滑动窗口
    if (this.buffer.length > SENSOR_CONFIG.WINDOW_SIZE) {
      this.buffer.shift();
    }

    // 触发样本回调
    if (this.onSample) {
      this.onSample(sample, this.sampleCount);
    }

    // 窗口数据就绪时触发回调
    if (this.buffer.length >= SENSOR_CONFIG.WINDOW_SIZE && this.onWindowReady) {
      this.onWindowReady(this.getWindowData());
    }
  }

  /**
   * 停止采集
   */
  stop() {
    if (!this.isCollecting) {
      return;
    }

    this.isCollecting = false;
    if (this.sampleInterval) {
      clearInterval(this.sampleInterval);
      this.sampleInterval = null;
    }

    console.log(`停止采集，共采集 ${this.sampleCount} 个样本`);
  }

  /**
   * 获取当前窗口数据
   */
  getWindowData() {
    return [...this.buffer];
  }

  /**
   * 获取最近N个样本
   */
  getRecentSamples(n) {
    return this.buffer.slice(-n);
  }

  /**
   * 清空缓冲区
   */
  clear() {
    this.buffer = [];
    this.sampleCount = 0;
  }

  /**
   * 获取采集状态
   */
  getStatus() {
    return {
      isCollecting: this.isCollecting,
      bufferSize: this.buffer.length,
      sampleCount: this.sampleCount,
      currentScenario: this.currentScenario
    };
  }

  /**
   * 切换场景（用于演示）
   */
  switchScenario(scenario) {
    this.currentScenario = scenario;
    console.log(`切换场景到: ${scenario}`);
  }

  /**
   * 注入外部数据（用于测试）
   */
  injectData(samples) {
    if (Array.isArray(samples)) {
      samples.forEach(sample => this.processSample(sample));
    } else {
      this.processSample(samples);
    }
  }
}

export default new DataCollector();

/**
 * 体态识别引擎
 * 基于规则+轻量决策树的体态分类
 */

import { POSTURE_TYPES, SENSOR_CONFIG } from '../utils/constants';
import featureExtractor from './feature-extractor';
import dataCollector from './data-collector';

class PostureEngine {
  constructor() {
    this.currentType = POSTURE_TYPES.NORMAL;
    this.anomalyStartTime = null;
    this.lastReminderTime = 0;
    this.onPostureDetected = null;
    this.onPostureChange = null;
    this.anomalyHistory = [];
    this.confidenceThreshold = 0.75;
  }

  /**
   * 主分类函数
   * @param {Object} features - 特征向量
   * @returns {Object} 分类结果
   */
  classify(features) {
    if (!features) {
      return {
        type: POSTURE_TYPES.NORMAL,
        confidence: 1.0,
        reason: '无数据'
      };
    }

    // 规则1：低头前倾
    // 俯仰角 > 30° 且持续增大
    if (features.pitchMean > 30) {
      const confidence = Math.min(0.95, 0.8 + features.pitchMean / 100);
      if (confidence >= this.confidenceThreshold) {
        return {
          type: POSTURE_TYPES.HEAD_DOWN,
          confidence: confidence,
          reason: `俯仰角 ${features.pitchMean.toFixed(1)}°`
        };
      }
    }

    // 规则2：久坐伏案
    // 合加速度接近1g（静止）+ 俯仰角 > 15° + 加速度方差小
    if (features.totalAccMean > 0.9 && features.totalAccMean < 1.1 &&
        features.pitchMean > 15 && features.accVarX < 0.01) {
      const confidence = Math.min(0.9, 0.75 + features.pitchMean / 200);
      if (confidence >= this.confidenceThreshold) {
        return {
          type: POSTURE_TYPES.SITTING_LONG,
          confidence: confidence,
          reason: `静止 + 俯仰角 ${features.pitchMean.toFixed(1)}°`
        };
      }
    }

    // 规则3：跷二郎腿
    // Z轴陀螺仪周期性波动 + 横滚角波动
    if (features.gyroVarZ > 0.05 && features.rollMean > 15) {
      const confidence = Math.min(0.85, 0.7 + features.gyroVarZ);
      if (confidence >= this.confidenceThreshold) {
        return {
          type: POSTURE_TYPES.CROSS_LEGS,
          confidence: confidence,
          reason: `Z轴波动 ${features.gyroVarZ.toFixed(3)}`
        };
      }
    }

    return {
      type: POSTURE_TYPES.NORMAL,
      confidence: 1.0,
      reason: '姿态正常'
    };
  }

  /**
   * 处理传感器样本
   */
  processSample(sample) {
    const windowData = dataCollector.getWindowData();

    // 窗口数据不足时跳过
    if (windowData.length < SENSOR_CONFIG.WINDOW_SIZE) {
      return null;
    }

    // 提取特征
    const features = featureExtractor.extract(windowData);

    // 分类
    const result = this.classify(features);

    // 异常持续时间判断
    const now = Date.now();
    if (result.type !== POSTURE_TYPES.NORMAL) {
      if (this.currentType === result.type) {
        // 持续异常
        const duration = now - this.anomalyStartTime;

        // 记录异常事件
        this.recordAnomaly(result, duration);

        // 持续时间超过阈值 且 冷却时间已过
        if (duration > SENSOR_CONFIG.MIN_DURATION &&
            now - this.lastReminderTime > SENSOR_CONFIG.REMINDER_COOLDOWN) {
          this.lastReminderTime = now;
          if (this.onPostureDetected) {
            this.onPostureDetected(result, duration);
          }
        }
      } else {
        // 新异常开始
        this.currentType = result.type;
        this.anomalyStartTime = now;

        if (this.onPostureChange) {
          this.onPostureChange(result, 'start');
        }
      }
    } else {
      // 恢复正常
      if (this.currentType !== POSTURE_TYPES.NORMAL) {
        if (this.onPostureChange) {
          this.onPostureChange({ type: this.currentType }, 'end');
        }
      }
      this.currentType = POSTURE_TYPES.NORMAL;
      this.anomalyStartTime = null;
    }

    return {
      ...result,
      features: {
        pitchMean: features.pitchMean,
        rollMean: features.rollMean,
        totalAccMean: features.totalAccMean
      }
    };
  }

  /**
   * 记录异常事件
   */
  recordAnomaly(result, duration) {
    // 检查是否已经记录过当前异常
    const lastRecord = this.anomalyHistory[this.anomalyHistory.length - 1];
    if (lastRecord && lastRecord.type === result.type) {
      // 更新持续时间
      lastRecord.duration = duration;
      lastRecord.confidence = result.confidence;
    } else {
      // 新增记录
      this.anomalyHistory.push({
        type: result.type,
        confidence: result.confidence,
        reason: result.reason,
        startTime: this.anomalyStartTime,
        duration: duration,
        timestamp: Date.now()
      });

      // 保留最近100条记录
      if (this.anomalyHistory.length > 100) {
        this.anomalyHistory.shift();
      }
    }
  }

  /**
   * 获取异常历史
   */
  getHistory() {
    return [...this.anomalyHistory];
  }

  /**
   * 获取今日异常统计
   */
  getTodayStats() {
    const today = new Date();
    today.setHours(0, 0, 0, 0);
    const todayStart = today.getTime();

    const todayAnomalies = this.anomalyHistory.filter(
      record => record.timestamp >= todayStart
    );

    // 按类型统计
    const typeCount = {};
    todayAnomalies.forEach(record => {
      typeCount[record.type] = (typeCount[record.type] || 0) + 1;
    });

    return {
      total: todayAnomalies.length,
      byType: typeCount,
      records: todayAnomalies
    };
  }

  /**
   * 计算健康评分
   */
  calculateHealthScore() {
    const stats = this.getTodayStats();
    let score = 100;

    // 每次异常扣分
    score -= stats.total * 5;

    // 根据异常类型扣分
    if (stats.byType[POSTURE_TYPES.HEAD_DOWN]) {
      score -= stats.byType[POSTURE_TYPES.HEAD_DOWN] * 3;
    }
    if (stats.byType[POSTURE_TYPES.SITTING_LONG]) {
      score -= stats.byType[POSTURE_TYPES.SITTING_LONG] * 2;
    }
    if (stats.byType[POSTURE_TYPES.CROSS_LEGS]) {
      score -= stats.byType[POSTURE_TYPES.CROSS_LEGS] * 4;
    }

    return Math.max(0, Math.min(100, score));
  }

  /**
   * 重置状态
   */
  reset() {
    this.currentType = POSTURE_TYPES.NORMAL;
    this.anomalyStartTime = null;
    this.lastReminderTime = 0;
    this.anomalyHistory = [];
  }

  /**
   * 设置置信度阈值
   */
  setConfidenceThreshold(threshold) {
    this.confidenceThreshold = Math.max(0, Math.min(1, threshold));
  }

  /**
   * 获取当前状态
   */
  getStatus() {
    return {
      currentType: this.currentType,
      anomalyStartTime: this.anomalyStartTime,
      anomalyDuration: this.anomalyStartTime ? Date.now() - this.anomalyStartTime : 0,
      historyCount: this.anomalyHistory.length,
      healthScore: this.calculateHealthScore()
    };
  }
}

export default new PostureEngine();

/**
 * 数据脱敏引擎
 * 对敏感字段进行模糊化、匿名化处理
 */

import { DESENSITIZE_RULES } from '../utils/constants';

class Desensitizer {
  /**
   * 时间戳模糊化
   * @param {number} timestamp - 原始时间戳
   * @param {string} granularity - 模糊粒度：'hour' | 'day'
   * @returns {string} 模糊后的时间字符串
   */
  fuzzTimestamp(timestamp, granularity = DESENSITIZE_RULES.TIMESTAMP.granularity) {
    const date = new Date(timestamp);

    switch (granularity) {
      case 'hour':
        date.setMinutes(0, 0, 0);
        break;
      case 'day':
        date.setHours(0, 0, 0, 0);
        break;
      case 'month':
        date.setDate(1);
        date.setHours(0, 0, 0, 0);
        break;
    }

    return date.toISOString().replace('T', ' ').substring(0, 19);
  }

  /**
   * 心率区间归一化
   * @param {number} bpm - 原始心率
   * @param {number} interval - 区间大小
   * @returns {string} 区间字符串
   */
  normalizeHeartRate(bpm, interval = DESENSITIZE_RULES.HEART_RATE.interval) {
    const base = Math.floor(bpm / interval) * interval;
    return `${base}-${base + interval}`;
  }

  /**
   * GPS网格编码
   * @param {number} lat - 纬度
   * @param {number} lon - 经度
   * @param {number} gridSize - 网格大小（米）
   * @returns {Object} 网格编码结果
   */
  gridEncode(lat, lon, gridSize = DESENSITIZE_RULES.GPS.gridSize) {
    // 将经纬度转换为网格编码
    // 纬度1度约111km，经度1度约111km*cos(lat)
    const latGrid = Math.floor(lat * 111000 / gridSize);
    const lonGrid = Math.floor(lon * 111000 * Math.cos(lat * Math.PI / 180) / gridSize);

    // 生成网格ID
    const gridLatChar = String.fromCharCode(65 + (Math.abs(latGrid) % 26));
    const gridId = `Grid-${gridLatChar}${Math.abs(lonGrid) % 100}`;

    // 添加随机偏移（增强隐私）
    const offsetLat = (Math.random() - 0.5) * gridSize / 111000;
    const offsetLon = (Math.random() - 0.5) * gridSize / (111000 * Math.cos(lat * Math.PI / 180));

    return {
      gridId,
      gridSize,
      offsetLat: parseFloat(offsetLat.toFixed(6)),
      offsetLon: parseFloat(offsetLon.toFixed(6))
    };
  }

  /**
   * 步数聚合
   * @param {number} steps - 原始步数
   * @param {number} interval - 聚合间隔
   * @returns {number} 聚合后的步数
   */
  aggregateSteps(steps, interval = 100) {
    const base = Math.floor(steps / interval) * interval;
    return base;
  }

  /**
   * 加速度数据保留（体态分析必需）
   * @param {Object} sample - 加速度样本
   * @param {number} precision - 小数精度
   * @returns {Object} 处理后的样本
   */
  preserveAcceleration(sample, precision = 2) {
    return {
      ax: parseFloat(sample.ax.toFixed(precision)),
      ay: parseFloat(sample.ay.toFixed(precision)),
      az: parseFloat(sample.az.toFixed(precision)),
      timestamp: this.fuzzTimestamp(sample.timestamp, 'day')
    };
  }

  /**
   * 处理心率数据
   * @param {Array} records - 心率记录数组
   * @returns {Array} 脱敏后的心率数据
   */
  processHeartRate(records) {
    if (!Array.isArray(records)) {
      return [];
    }

    return records.map(record => ({
      bpmRange: this.normalizeHeartRate(record.bpm),
      timestamp: this.fuzzTimestamp(record.timestamp),
      // 不保留精确BPM
    }));
  }

  /**
   * 处理轨迹数据
   * @param {Array} records - GPS记录数组
   * @returns {Array} 脱敏后的轨迹数据
   */
  processTrajectory(records) {
    if (!Array.isArray(records)) {
      return [];
    }

    return records.map(record => ({
      grid: this.gridEncode(record.lat, record.lon),
      timestamp: this.fuzzTimestamp(record.timestamp),
      // 不保留精确坐标
    }));
  }

  /**
   * 处理步数数据
   * @param {Array} records - 步数记录数组
   * @returns {Array} 脱敏后的步数数据
   */
  processStepData(records) {
    if (!Array.isArray(records)) {
      return [];
    }

    return records.map(record => ({
      steps: this.aggregateSteps(record.steps),
      timestamp: this.fuzzTimestamp(record.timestamp),
    }));
  }

  /**
   * 处理姿态数据（保留特征，用于体态分析）
   * @param {Array} samples - 传感器样本数组
   * @returns {Array} 处理后的姿态数据
   */
  processPostureData(samples) {
    if (!Array.isArray(samples)) {
      return [];
    }

    return samples.map(sample => this.preserveAcceleration(sample));
  }

  /**
   * 通用脱敏处理
   * @param {any} data - 原始数据
   * @param {string} type - 数据类型
   * @returns {any} 脱敏后的数据
   */
  process(data, type) {
    switch (type) {
      case 'heartRate':
        return this.processHeartRate(data);
      case 'trajectory':
        return this.processTrajectory(data);
      case 'steps':
        return this.processStepData(data);
      case 'posture':
        return this.processPostureData(data);
      default:
        console.warn(`未知的数据类型: ${type}`);
        return data;
    }
  }

  /**
   * 批量脱敏处理
   * @param {Object} dataSet - 数据集 { type: data }
   * @returns {Object} 脱敏后的数据集
   */
  processBatch(dataSet) {
    const result = {};
    for (const [type, data] of Object.entries(dataSet)) {
      result[type] = this.process(data, type);
    }
    return result;
  }

  /**
   * 生成脱敏报告
   * @param {Object} original - 原始数据
   * @param {Object} desensitized - 脱敏后数据
   * @returns {Object} 脱敏报告
   */
  generateReport(original, desensitized) {
    const report = {
      timestamp: new Date().toISOString(),
      totalRecords: 0,
      processedRecords: 0,
      details: []
    };

    for (const [type, origData] of Object.entries(original)) {
      const desData = desensitized[type];
      const count = Array.isArray(origData) ? origData.length : 1;

      report.totalRecords += count;
      report.processedRecords += count;

      report.details.push({
        type,
        originalCount: count,
        processedCount: count,
        status: 'success'
      });
    }

    return report;
  }
}

export default new Desensitizer();

/**
 * AES加密引擎
 * 轻量化AES-128-CBC加密实现
 */

import { CRYPTO_CONFIG } from '../utils/constants';

class CryptoEngine {
  constructor() {
    this.keys = {};
    this.initialized = false;
  }

  /**
   * 初始化加密引擎
   * @param {string} deviceUID - 设备唯一ID
   */
  init(deviceUID = 'default-device') {
    this.deviceUID = deviceUID;
    this.initialized = true;
    this.generateKeys();
    console.log('加密引擎初始化完成');
  }

  /**
   * 生成各层级密钥
   */
  generateKeys() {
    for (const [level, config] of Object.entries(CRYPTO_CONFIG.LEVELS)) {
      this.keys[level] = this.deriveKey(this.deviceUID, config.name, level);
    }
  }

  /**
   * 密钥派生（基于设备UID和盐值）
   * @param {string} deviceUID - 设备唯一ID
   * @param {string} salt - 盐值
   * @param {string} level - 加密层级
   * @returns {Array} 16字节密钥
   */
  deriveKey(deviceUID, salt, level) {
    // 使用简化的密钥派生函数
    // 实际项目中应使用HKDF或PBKDF2
    const baseStr = `${deviceUID}-${salt}-${level}-posture-guard`;
    let hash = 0;

    for (let i = 0; i < baseStr.length; i++) {
      const char = baseStr.charCodeAt(i);
      hash = ((hash << 5) - hash) + char;
      hash = hash & hash; // 转换为32位整数
    }

    // 生成16字节密钥
    const key = new Array(16);
    for (let i = 0; i < 16; i++) {
      // 使用多个hash值组合生成更随机的密钥
      const tempHash = this.simpleHash(baseStr + i.toString());
      key[i] = (tempHash >> ((i % 4) * 8)) & 0xFF;
    }

    return key;
  }

  /**
   * 简单哈希函数
   */
  simpleHash(str) {
    let hash = 5381;
    for (let i = 0; i < str.length; i++) {
      hash = ((hash << 5) + hash) + str.charCodeAt(i);
      hash = hash & hash;
    }
    return Math.abs(hash);
  }

  /**
   * 生成随机IV
   * @returns {Array} 16字节IV
   */
  generateIV() {
    const iv = new Array(16);
    for (let i = 0; i < 16; i++) {
      iv[i] = Math.floor(Math.random() * 256);
    }
    return iv;
  }

  /**
   * PKCS#7填充
   * @param {Array} data - 原始数据
   * @param {number} blockSize - 块大小
   * @returns {Array} 填充后的数据
   */
  pkcs7Pad(data, blockSize = 16) {
    const padLen = blockSize - (data.length % blockSize);
    return [...data, ...new Array(padLen).fill(padLen)];
  }

  /**
   * PKCS#7去填充
   * @param {Array} data - 填充后的数据
   * @returns {Array} 原始数据
   */
  pkcs7Unpad(data) {
    if (!data || data.length === 0) {
      return data;
    }
    const padLen = data[data.length - 1];
    if (padLen > 16 || padLen === 0) {
      return data; // 无效填充，返回原数据
    }
    return data.slice(0, data.length - padLen);
  }

  /**
   * AES S-Box替换（简化版）
   */
  sBox(byte) {
    // 简化的S-Box实现
    const sbox = [
      0x63, 0x7c, 0x77, 0x7b, 0xf2, 0x6b, 0x6f, 0xc5, 0x30, 0x01, 0x67, 0x2b, 0xfe, 0xd7, 0xab, 0x76,
      0xca, 0x82, 0xc9, 0x7d, 0xfa, 0x59, 0x47, 0xf0, 0xad, 0xd4, 0xa2, 0xaf, 0x9c, 0xa4, 0x72, 0xc0,
      0xb7, 0xfd, 0x93, 0x26, 0x36, 0x3f, 0xf7, 0xcc, 0x34, 0xa5, 0xe5, 0xf1, 0x71, 0xd8, 0x31, 0x15,
      0x04, 0xc7, 0x23, 0xc3, 0x18, 0x96, 0x05, 0x9a, 0x07, 0x12, 0x80, 0xe2, 0xeb, 0x27, 0xb2, 0x75,
      0x09, 0x83, 0x2c, 0x1a, 0x1b, 0x6e, 0x5a, 0xa0, 0x52, 0x3b, 0xd6, 0xb3, 0x29, 0xe3, 0x2f, 0x84,
      0x53, 0xd1, 0x00, 0xed, 0x20, 0xfc, 0xb1, 0x5b, 0x6a, 0xcb, 0xbe, 0x39, 0x4a, 0x4c, 0x58, 0xcf,
      0xd0, 0xef, 0xaa, 0xfb, 0x43, 0x4d, 0x33, 0x85, 0x45, 0xf9, 0x02, 0x7f, 0x50, 0x3c, 0x9f, 0xa8,
      0x51, 0xa3, 0x40, 0x8f, 0x92, 0x9d, 0x38, 0xf5, 0xbc, 0xb6, 0xda, 0x21, 0x10, 0xff, 0xf3, 0xd2,
      0xcd, 0x0c, 0x13, 0xec, 0x5f, 0x97, 0x44, 0x17, 0xc4, 0xa7, 0x7e, 0x3d, 0x64, 0x5d, 0x19, 0x73,
      0x60, 0x81, 0x4f, 0xdc, 0x22, 0x2a, 0x90, 0x88, 0x46, 0xee, 0xb8, 0x14, 0xde, 0x5e, 0x0b, 0xdb,
      0xe0, 0x32, 0x3a, 0x0a, 0x49, 0x06, 0x24, 0x5c, 0xc2, 0xd3, 0xac, 0x62, 0x91, 0x95, 0xe4, 0x79,
      0xe7, 0xc8, 0x37, 0x6d, 0x8d, 0xd5, 0x4e, 0xa9, 0x6c, 0x56, 0xf4, 0xea, 0x65, 0x7a, 0xae, 0x08,
      0xba, 0x78, 0x25, 0x2e, 0x1c, 0xa6, 0xb4, 0xc6, 0xe8, 0xdd, 0x74, 0x1f, 0x4b, 0xbd, 0x8b, 0x8a,
      0x70, 0x3e, 0xb5, 0x66, 0x48, 0x03, 0xf6, 0x0e, 0x61, 0x35, 0x57, 0xb9, 0x86, 0xc1, 0x1d, 0x9e,
      0xe1, 0xf8, 0x98, 0x11, 0x69, 0xd9, 0x8e, 0x94, 0x9b, 0x1e, 0x87, 0xe9, 0xce, 0x55, 0x28, 0xdf,
      0x8c, 0xa1, 0x89, 0x0d, 0xbf, 0xe6, 0x42, 0x68, 0x41, 0x99, 0x2d, 0x0f, 0xb0, 0x54, 0xbb, 0x16
    ];
    return sbox[byte & 0xFF];
  }

  /**
   * 简化的AES加密轮函数
   */
  aesRound(state, roundKey) {
    const result = new Array(16);
    for (let i = 0; i < 16; i++) {
      result[i] = this.sBox(state[i] ^ roundKey[i]);
    }
    return result;
  }

  /**
   * 加密单个块（16字节）
   */
  encryptBlock(block, key) {
    let state = [...block];
    const numRounds = 10;

    // 初始轮密钥加
    for (let i = 0; i < 16; i++) {
      state[i] = state[i] ^ key[i];
    }

    // 轮函数
    for (let round = 1; round < numRounds; round++) {
      const roundKey = key.slice(0, 16); // 简化：使用相同轮密钥
      state = this.aesRound(state, roundKey);
    }

    return state;
  }

  /**
   * 解密单个块（16字节）
   */
  decryptBlock(block, key) {
    // 简化版解密：逆向AES轮函数
    let state = [...block];

    // 逆向轮函数
    for (let round = 0; round < 10; round++) {
      const roundKey = key.slice(0, 16);
      // 简化：使用XOR逆运算
      for (let i = 0; i < 16; i++) {
        state[i] = state[i] ^ roundKey[i];
      }
    }

    return state;
  }

  /**
   * CBC模式加密
   */
  cbcEncrypt(plaintext, key, iv) {
    const data = this.pkcs7Pad(plaintext);
    const blocks = [];
    let prevBlock = [...iv];

    // 分块
    for (let i = 0; i < data.length; i += 16) {
      blocks.push(data.slice(i, i + 16));
    }

    // 加密每个块
    const ciphertext = [];
    for (const block of blocks) {
      // CBC: 明文块 XOR 前一个密文块
      const xored = block.map((b, i) => b ^ prevBlock[i]);
      const encrypted = this.encryptBlock(xored, key);
      ciphertext.push(...encrypted);
      prevBlock = encrypted;
    }

    return ciphertext;
  }

  /**
   * CBC模式解密
   */
  cbcDecrypt(ciphertext, key, iv) {
    const blocks = [];
    let prevBlock = [...iv];

    // 分块
    for (let i = 0; i < ciphertext.length; i += 16) {
      blocks.push(ciphertext.slice(i, i + 16));
    }

    // 解密每个块
    const plaintext = [];
    for (const block of blocks) {
      const decrypted = this.decryptBlock(block, key);
      // CBC: 解密后的块 XOR 前一个密文块
      const xored = decrypted.map((b, i) => b ^ prevBlock[i]);
      plaintext.push(...xored);
      prevBlock = block;
    }

    // 去填充
    return this.pkcs7Unpad(plaintext);
  }

  /**
   * 加密数据
   * @param {any} data - 要加密的数据
   * @param {string} level - 加密层级
   * @returns {Object} 加密结果
   */
  encryptData(data, level = 'L1') {
    if (!this.initialized) {
      this.init();
    }

    const plaintext = JSON.stringify(data);
    const plaintextBytes = new TextEncoder().encode(plaintext);
    const iv = this.generateIV();
    const key = this.keys[level] || this.keys['L1'];

    const ciphertext = this.cbcEncrypt(Array.from(plaintextBytes), key, iv);

    return {
      ciphertext,
      iv,
      level,
      timestamp: Date.now()
    };
  }

  /**
   * 解密数据
   * @param {Object} encryptedData - 加密数据
   * @returns {any} 解密后的数据
   */
  decryptData(encryptedData) {
    if (!this.initialized) {
      this.init();
    }

    const { ciphertext, iv, level } = encryptedData;
    const key = this.keys[level] || this.keys['L1'];

    const plaintextBytes = this.cbcDecrypt(ciphertext, key, iv);
    const plaintext = new TextDecoder().decode(new Uint8Array(plaintextBytes));

    return JSON.parse(plaintext);
  }

  /**
   * 计算数据的简单校验和
   */
  calculateChecksum(data) {
    const str = JSON.stringify(data);
    let checksum = 0;
    for (let i = 0; i < str.length; i++) {
      checksum = ((checksum << 5) - checksum) + str.charCodeAt(i);
      checksum = checksum & checksum;
    }
    return Math.abs(checksum).toString(16).padStart(8, '0');
  }

  /**
   * 安全清零密钥
   */
  clearKeys() {
    for (const level of Object.keys(this.keys)) {
      this.keys[level] = new Array(16).fill(0);
      delete this.keys[level];
    }
    this.initialized = false;
    console.log('密钥已安全清零');
  }

  /**
   * 获取加密状态
   */
  getStatus() {
    return {
      initialized: this.initialized,
      keyLevels: Object.keys(this.keys),
      algorithm: CRYPTO_CONFIG.ALGORITHM
    };
  }
}

export default new CryptoEngine();

/**
 * 存储管理器
 * 负责加密数据的本地存储、读取和生命周期管理
 */

import cryptoEngine from './crypto-engine';
import { CRYPTO_CONFIG, STORAGE_KEYS } from '../utils/constants';

class StorageManager {
  constructor() {
    this.storageKey = 'posture-guard-data';
    this.initialized = false;
  }

  /**
   * 初始化存储管理器
   */
  init() {
    if (this.initialized) return;

    // 初始化加密引擎
    cryptoEngine.init();
    this.initialized = true;

    // 执行启动时清理
    this.cleanup();

    console.log('存储管理器初始化完成');
  }

  /**
   * 保存加密数据
   * @param {string} key - 数据键名
   * @param {any} data - 要保存的数据
   * @param {Object} options - 选项
   * @returns {boolean} 是否成功
   */
  save(key, data, options = {}) {
    if (!this.initialized) {
      this.init();
    }

    const { level = 'L1', expiryDays = CRYPTO_CONFIG.LEVELS.L1.retentionDays } = options;

    try {
      // 加密数据
      const encrypted = cryptoEngine.encryptData(data, level);

      // 添加元数据
      const record = {
        ...encrypted,
        createTime: Date.now(),
        expiryTime: Date.now() + expiryDays * 24 * 60 * 60 * 1000,
        key,
        checksum: cryptoEngine.calculateChecksum(data)
      };

      // 读取现有数据
      const allData = this.getAll();
      allData[key] = record;

      // 保存到本地存储
      this.persistData(allData);

      console.log(`数据已保存: ${key}, 层级: ${level}, 有效期: ${expiryDays}天`);
      return true;
    } catch (e) {
      console.error('保存数据失败:', e);
      return false;
    }
  }

  /**
   * 读取并解密数据
   * @param {string} key - 数据键名
   * @returns {Object} { expired: boolean, data: any }
   */
  load(key) {
    const allData = this.getAll();
    const record = allData[key];

    if (!record) {
      return { expired: false, data: null };
    }

    // 检查是否过期
    if (Date.now() > record.expiryTime) {
      console.log(`数据已过期: ${key}`);
      return { expired: true, data: null };
    }

    try {
      const data = cryptoEngine.decryptData(record);

      // 验证校验和
      const checksum = cryptoEngine.calculateChecksum(data);
      if (checksum !== record.checksum) {
        console.warn(`数据校验失败: ${key}`);
      }

      return { expired: false, data };
    } catch (e) {
      console.error('解密数据失败:', e);
      return { expired: false, data: null };
    }
  }

  /**
   * 获取所有数据
   */
  getAll() {
    try {
      const raw = this.getPersistedData();
      return raw || {};
    } catch (e) {
      console.error('读取数据失败:', e);
      return {};
    }
  }

  /**
   * 删除指定数据
   * @param {string} key - 数据键名
   */
  delete(key) {
    const allData = this.getAll();
    delete allData[key];
    this.persistData(allData);
    console.log(`数据已删除: ${key}`);
  }

  /**
   * 安全删除（覆写清零）
   * @param {string} key - 数据键名
   */
  secureDelete(key) {
    const allData = this.getAll();
    if (allData[key]) {
      // 用随机数据覆写
      allData[key].ciphertext = new Array(1024).fill(0).map(() =>
        Math.floor(Math.random() * 256)
      );
      allData[key].expiryTime = 0;
      this.persistData(allData);
    }

    // 然后删除
    this.delete(key);
    console.log(`数据已安全删除: ${key}`);
  }

  /**
   * 清理过期数据
   * @returns {number} 清理的数据数量
   */
  cleanup() {
    const allData = this.getAll();
    const now = Date.now();
    let cleanedCount = 0;

    for (const [key, record] of Object.entries(allData)) {
      if (now > record.expiryTime) {
        delete allData[key];
        cleanedCount++;
      }
    }

    if (cleanedCount > 0) {
      this.persistData(allData);
      console.log(`已清理 ${cleanedCount} 条过期数据`);
    }

    return cleanedCount;
  }

  /**
   * 获取数据统计信息
   */
  getStats() {
    const allData = this.getAll();
    const now = Date.now();
    let activeCount = 0;
    let expiredCount = 0;
    let totalSize = 0;

    for (const [key, record] of Object.entries(allData)) {
      if (now > record.expiryTime) {
        expiredCount++;
      } else {
        activeCount++;
      }
      totalSize += JSON.stringify(record).length;
    }

    return {
      activeCount,
      expiredCount,
      totalCount: activeCount + expiredCount,
      estimatedSize: `${(totalSize / 1024).toFixed(2)} KB`
    };
  }

  /**
   * 获取数据生命周期信息
   */
  getLifecycleInfo(key) {
    const allData = this.getAll();
    const record = allData[key];

    if (!record) {
      return null;
    }

    const now = Date.now();
    const totalLifetime = record.expiryTime - record.createTime;
    const remaining = Math.max(0, record.expiryTime - now);
    const progress = 1 - (remaining / totalLifetime);

    return {
      key,
      createTime: new Date(record.createTime).toISOString(),
      expiryTime: new Date(record.expiryTime).toISOString(),
      level: record.level,
      remainingDays: Math.ceil(remaining / (24 * 60 * 60 * 1000)),
      progress: Math.min(1, Math.max(0, progress)),
      isExpired: now > record.expiryTime
    };
  }

  /**
   * 持久化数据（模拟本地存储）
   * 实际项目中应使用系统文件API
   */
  persistData(data) {
    try {
      // 模拟localStorage
      if (typeof localStorage !== 'undefined') {
        localStorage.setItem(this.storageKey, JSON.stringify(data));
      } else {
        // 模拟器环境下使用内存存储
        this._memoryStorage = data;
      }
    } catch (e) {
      console.error('持久化数据失败:', e);
    }
  }

  /**
   * 获取持久化数据
   */
  getPersistedData() {
    try {
      if (typeof localStorage !== 'undefined') {
        const raw = localStorage.getItem(this.storageKey);
        return raw ? JSON.parse(raw) : {};
      } else {
        return this._memoryStorage || {};
      }
    } catch (e) {
      console.error('获取持久化数据失败:', e);
      return {};
    }
  }

  /**
   * 清空所有数据
   */
  clearAll() {
    this.persistData({});
    console.log('所有数据已清空');
  }

  /**
   * 导出数据（用于备份）
   * @param {string} password - 导出密码
   * @returns {Object} 加密的导出数据
   */
  exportData(password = 'default-password') {
    const allData = this.getAll();
    return cryptoEngine.encryptData(allData, 'L2');
  }

  /**
   * 导入数据（用于恢复）
   * @param {Object} encryptedData - 加密的导入数据
   */
  importData(encryptedData) {
    try {
      const data = cryptoEngine.decryptData(encryptedData);
      this.persistData(data);
      console.log('数据导入成功');
      return true;
    } catch (e) {
      console.error('数据导入失败:', e);
      return false;
    }
  }
}

