/**
 * 提醒管理器
 * 负责体态异常提醒的触发和管理
 */

import { POSTURE_TYPES, SENSOR_CONFIG, REMINDER_MESSAGES } from '../utils/constants';

class ReminderManager {
  constructor() {
    this.lastReminderTime = 0;
    this.reminderHistory = [];
    this.onReminder = null;
    this.onVibrate = null;
    this.enabled = true;
    this.soundEnabled = true;
  }

  /**
   * 检查冷却时间
   * @returns {boolean} 是否可以触发提醒
   */
  checkCooldown() {
    const now = Date.now();
    return now - this.lastReminderTime >= SENSOR_CONFIG.REMINDER_COOLDOWN;
  }

  /**
   * 获取提醒消息
   * @param {string} type - 异常类型
   * @param {number} duration - 持续时间（毫秒）
   * @returns {Object} 提醒消息
   */
  getReminderMessage(type, duration) {
    const baseMessage = REMINDER_MESSAGES[type] || {
      title: '提醒',
      message: '请注意姿势',
      icon: '💡'
    };

    // 根据持续时间调整消息
    const durationMinutes = Math.floor(duration / 60000);
    let intensity = '轻度';
    if (durationMinutes > 30) {
      intensity = '严重';
    } else if (durationMinutes > 15) {
      intensity = '中度';
    }

    return {
      ...baseMessage,
      duration: durationMinutes,
      intensity,
      timestamp: Date.now()
    };
  }

  /**
   * 触发提醒
   * @param {string} type - 异常类型
   * @param {number} duration - 持续时间
   * @returns {boolean} 是否成功触发
   */
  trigger(type, duration) {
    if (!this.enabled) {
      console.log('提醒已禁用');
      return false;
    }

    if (!this.checkCooldown()) {
      console.log('冷却中，跳过提醒');
      return false;
    }

    const reminder = this.getReminderMessage(type, duration);

    // 记录提醒历史
    this.reminderHistory.unshift({
      type,
      typeName: this.getTypeName(type),
      message: reminder.message,
      duration: reminder.duration,
      intensity: reminder.intensity,
      timestamp: Date.now()
    });

    // 保留最近50条记录
    if (this.reminderHistory.length > 50) {
      this.reminderHistory.pop();
    }

    this.lastReminderTime = Date.now();

    // 触发回调（用于UI显示）
    if (this.onReminder) {
      this.onReminder(reminder);
    }

    // 触发震动
    this.vibrate();

    console.log('提醒触发:', reminder);
    return true;
  }

  /**
   * 震动提醒
   */
  vibrate() {
    try {
      // 模拟震动效果
      console.log('震动: 200ms短震动');

      if (this.onVibrate) {
        this.onVibrate();
      }

      // 实际项目中应调用系统震动API
      // system.vibrator.vibrate({ mode: 'short' });
    } catch (e) {
      console.log('震动API不可用:', e);
    }
  }

  /**
   * 获取类型名称
   */
  getTypeName(type) {
    const names = {
      [POSTURE_TYPES.HEAD_DOWN]: '低头前倾',
      [POSTURE_TYPES.SITTING_LONG]: '久坐伏案',
      [POSTURE_TYPES.CROSS_LEGS]: '跷二郎腿',
      [POSTURE_TYPES.NORMAL]: '正常'
    };
    return names[type] || '未知';
  }

  /**
   * 获取提醒历史
   * @param {number} limit - 返回数量限制
   * @returns {Array} 提醒历史
   */
  getHistory(limit = 20) {
    return this.reminderHistory.slice(0, limit);
  }

  /**
   * 获取今日提醒统计
   */
  getTodayStats() {
    const today = new Date();
    today.setHours(0, 0, 0, 0);
    const todayStart = today.getTime();

    const todayReminders = this.reminderHistory.filter(
      record => record.timestamp >= todayStart
    );

    // 按类型统计
    const typeCount = {};
    todayReminders.forEach(record => {
      typeCount[record.type] = (typeCount[record.type] || 0) + 1;
    });

    return {
      total: todayReminders.length,
      byType: typeCount,
      records: todayReminders
    };
  }

  /**
   * 清空历史
   */
  clearHistory() {
    this.reminderHistory = [];
    console.log('提醒历史已清空');
  }

  /**
   * 启用/禁用提醒
   */
  setEnabled(enabled) {
    this.enabled = enabled;
    console.log(`提醒${enabled ? '已启用' : '已禁用'}`);
  }

  /**
   * 设置冷却时间
   */
  setCooldown(ms) {
    SENSOR_CONFIG.REMINDER_COOLDOWN = ms;
    console.log(`提醒冷却时间设置为: ${ms}ms`);
  }

  /**
   * 获取状态
   */
  getStatus() {
    return {
      enabled: this.enabled,
      lastReminderTime: this.lastReminderTime,
      historyCount: this.reminderHistory.length,
      cooldown: SENSOR_CONFIG.REMINDER_COOLDOWN,
      canRemind: this.checkCooldown()
    };
  }
}

export default new ReminderManager();

/**
 * 安全日志工具
 * 记录应用操作日志，支持脱敏
 */

import storageManager from '../core/storage-manager';

class Logger {
  constructor() {
    this.logs = [];
    this.maxLogs = 1000;
    this.logLevel = 'info'; // debug, info, warn, error
  }

  /**
   * 日志级别权重
   */
  getLevelWeight(level) {
    const weights = {
      debug: 0,
      info: 1,
      warn: 2,
      error: 3
    };
    return weights[level] || 0;
  }

  /**
   * 检查是否应该记录
   */
  shouldLog(level) {
    return this.getLevelWeight(level) >= this.getLevelWeight(this.logLevel);
  }

  /**
   * 添加日志
   */
  addLog(level, category, message, data = null) {
    if (!this.shouldLog(level)) {
      return;
    }

    const log = {
      timestamp: Date.now(),
      level,
      category,
      message,
      data: this.sanitizeData(data)
    };

    this.logs.unshift(log);

    // 保持日志数量限制
    if (this.logs.length > this.maxLogs) {
      this.logs.pop();
    }

    // 控制台输出
    this.consoleLog(log);

    return log;
  }

  /**
   * 脱敏处理日志数据
   */
  sanitizeData(data) {
    if (!data) return null;

    if (typeof data !== 'object') {
      return data;
    }

    const sanitized = { ...data };

    // 脱敏敏感字段
    const sensitiveFields = ['password', 'key', 'secret', 'token', 'uid'];

    for (const field of sensitiveFields) {
      if (sanitized[field]) {
        sanitized[field] = '***';
      }
    }

    // 脱敏心率数据
    if (sanitized.bpm) {
      sanitized.bpm = `${Math.floor(sanitized.bpm / 5) * 5}-${Math.floor(sanitized.bpm / 5) * 5 + 5}`;
    }

    // 脱敏GPS数据
    if (sanitized.lat && sanitized.lon) {
      delete sanitized.lat;
      delete sanitized.lon;
      sanitized.grid = 'Grid-XX';
    }

    return sanitized;
  }

  /**
   * 控制台输出
   */
  consoleLog(log) {
    const prefix = `[${log.level.toUpperCase()}][${log.category}]`;
    const message = `${prefix} ${log.message}`;

    switch (log.level) {
      case 'debug':
        console.log(message, log.data || '');
        break;
      case 'info':
        console.log(message, log.data || '');
        break;
      case 'warn':
        console.warn(message, log.data || '');
        break;
      case 'error':
        console.error(message, log.data || '');
        break;
    }
  }

  /**
   * 调试日志
   */
  debug(category, message, data) {
    return this.addLog('debug', category, message, data);
  }

  /**
   * 信息日志
   */
  info(category, message, data) {
    return this.addLog('info', category, message, data);
  }

  /**
   * 警告日志
   */
  warn(category, message, data) {
    return this.addLog('warn', category, message, data);
  }

  /**
   * 错误日志
   */
  error(category, message, data) {
    return this.addLog('error', category, message, data);
  }

  /**
   * 记录体态识别日志
   */
  logPostureDetection(result, duration) {
    this.info('POSTURE', `体态检测: ${result.type}`, {
      confidence: result.confidence,
      reason: result.reason,
      duration: Math.floor(duration / 1000)
    });
  }

  /**
   * 记录提醒触发日志
   */
  logReminderTrigger(type, message) {
    this.info('REMINDER', `提醒触发: ${type}`, { message });
  }

  /**
   * 记录数据加密日志
   */
  logEncryption(action, key, success) {
    this.info('CRYPTO', `加密操作: ${action}`, { key, success });
  }

  /**
   * 记录数据脱敏日志
   */
  logDesensitization(type, count) {
    this.info('DESENSITIZE', `数据脱敏: ${type}`, { count });
  }

  /**
   * 记录存储操作日志
   */
  logStorage(action, key, success) {
    this.debug('STORAGE', `存储操作: ${action}`, { key, success });
  }

  /**
   * 获取日志
   */
  getLogs(options = {}) {
    const { level, category, limit = 100 } = options;

    let filtered = this.logs;

    if (level) {
      filtered = filtered.filter(log => log.level === level);
    }

    if (category) {
      filtered = filtered.filter(log => log.category === category);
    }

    return filtered.slice(0, limit);
  }

  /**
   * 获取日志统计
   */
  getStats() {
    const stats = {
      total: this.logs.length,
      byLevel: {},
      byCategory: {}
    };

    this.logs.forEach(log => {
      stats.byLevel[log.level] = (stats.byLevel[log.level] || 0) + 1;
      stats.byCategory[log.category] = (stats.byCategory[log.category] || 0) + 1;
    });

    return stats;
  }

  /**
   * 清空日志
   */
  clear() {
    this.logs = [];
    console.log('日志已清空');
  }

  /**
   * 导出日志
   */
  export() {
    return JSON.stringify(this.logs, null, 2);
  }

  /**
   * 设置日志级别
   */
  setLevel(level) {
    this.logLevel = level;
    console.log(`日志级别设置为: ${level}`);
  }
}

export default new Logger();

/**
