import { POSTURE_TYPES } from '../utils/constants';

class TestSuite {
  constructor() {
    this.results = [];
    this.passed = 0;
    this.failed = 0;
  }

  /**
   * 运行所有测试
   */
  runAll() {
    console.log('========================================');
    console.log('体态守护 - 测试套件');
    console.log('========================================\n');

    this.testFeatureExtractor();
    this.testPostureEngine();
    this.testDesensitizer();
    this.testCryptoEngine();
