  /**
   * 测试特征提取器
   */
  testFeatureExtractor() {
    console.log('--- 测试特征提取器 ---');

    // 测试空数据
    const emptyFeatures = featureExtractor.extract([]);
    this.assert(emptyFeatures !== null, '空数据返回空特征');
    this.assert(emptyFeatures.accMeanX === 0, '空数据均值为0');

    // 测试正常数据
    const normalData = sensorMock.generate(POSTURE_TYPES.NORMAL, 2000);
    const normalFeatures = featureExtractor.extract(normalData);
    this.assert(normalFeatures !== null, '正常数据提取特征');
    this.assert(typeof normalFeatures.accMeanX === 'number', '特征为数字类型');
    this.assert(normalFeatures.pitchMean > -50 && normalFeatures.pitchMean < 50, '俯仰角在合理范围');

    // 测试低头数据
    const headDownData = sensorMock.generate(POSTURE_TYPES.HEAD_DOWN, 10000);
    const headDownFeatures = featureExtractor.extract(headDownData);
    this.assert(headDownFeatures.pitchMean > 20, '低头数据俯仰角大于20度');

    console.log('');
  }

  /**
   * 测试体态识别引擎
   */
  testPostureEngine() {
    console.log('--- 测试体态识别引擎 ---');

    // 测试正常姿态
    const normalData = sensorMock.generate(POSTURE_TYPES.NORMAL, 2000);
    const normalFeatures = featureExtractor.extract(normalData);
    const normalResult = postureEngine.classify(normalFeatures);
    this.assert(normalResult.type === POSTURE_TYPES.NORMAL, '正常姿态识别');

    // 测试低头前倾
    const headDownData = sensorMock.generate(POSTURE_TYPES.HEAD_DOWN, 10000);
    const headDownFeatures = featureExtractor.extract(headDownData);
    const headDownResult = postureEngine.classify(headDownFeatures);
    this.assert(headDownResult.type === POSTURE_TYPES.HEAD_DOWN, '低头前倾识别');
    this.assert(headDownResult.confidence > 0.7, '低头识别置信度');

    // 测试久坐伏案
    const sittingData = sensorMock.generate(POSTURE_TYPES.SITTING_LONG, 10000);
    const sittingFeatures = featureExtractor.extract(sittingData);
    const sittingResult = postureEngine.classify(sittingFeatures);
    // 久坐识别可能需要更长时间的数据
    this.assert(sittingResult.type !== undefined, '久坐识别返回结果');

    console.log('');
  }

  /**
   * 测试数据脱敏引擎
   */
  testDesensitizer() {
    console.log('--- 测试数据脱敏引擎 ---');

    // 测试时间戳模糊化
    const timestamp = new Date('2026-08-20T14:32:15').getTime();
    const fuzzed = desensitizer.fuzzTimestamp(timestamp);
    this.assert(fuzzed.includes('14:00'), '时间戳模糊到小时');
    this.assert(!fuzzed.includes('32:15'), '分钟被模糊');

    // 测试心率区间归一化
    const hr72 = desensitizer.normalizeHeartRate(72);
    this.assert(hr72 === '70-75', '心率72归一化为70-75');

    const hr85 = desensitizer.normalizeHeartRate(85);
    this.assert(hr85 === '85-90', '心率85归一化为85-90');

    // 测试GPS网格编码
    const gps = desensitizer.gridEncode(39.916, 116.397);
    this.assert(gps.gridId.startsWith('Grid-'), 'GPS网格编码格式');
    this.assert(gps.offsetLat !== undefined, 'GPS有偏移');

    // 测试心率数据处理
    const hrRecords = [
      { bpm: 72, timestamp: Date.now() },
      { bpm: 85, timestamp: Date.now() - 60000 }
    ];
    const processedHR = desensitizer.processHeartRate(hrRecords);
    this.assert(processedHR.length === 2, '心率数据处理数量');
    this.assert(processedHR[0].bpmRange === '70-75', '心率脱敏结果');

    // 测试轨迹数据处理
    const轨迹 = [
      { lat: 39.916, lon: 116.397, timestamp: Date.now() }
    ];
    const processedTrajectory = desensitizer.processTrajectory(轨迹);
    this.assert(processedTrajectory[0].grid.gridId.startsWith('Grid-'), '轨迹脱敏结果');

    console.log('');
  }

  /**
   * 测试AES加密引擎
   */
  testCryptoEngine() {
    console.log('--- 测试AES加密引擎 ---');

    // 初始化
    cryptoEngine.init('test-device-uid');

    // 测试加密解密
    const testData = { heartRate: 72, timestamp: Date.now(), message: '测试数据' };
    const encrypted = cryptoEngine.encryptData(testData, 'L1');
    this.assert(encrypted.ciphertext.length > 0, '加密产生密文');
    this.assert(encrypted.iv.length === 16, 'IV长度为16');
    this.assert(encrypted.level === 'L1', '加密层级正确');

    const decrypted = cryptoEngine.decryptData(encrypted);
    this.assert(decrypted.heartRate === 72, '解密心率数据');
    this.assert(decrypted.message === '测试数据', '解密文本数据');

    // 测试校验和
    const checksum = cryptoEngine.calculateChecksum(testData);
    this.assert(checksum.length === 8, '校验和长度为8');

    // 测试不同层级加密
    const encryptedL2 = cryptoEngine.encryptData(testData, 'L2');
    const decryptedL2 = cryptoEngine.decryptData(encryptedL2);
    this.assert(decryptedL2.heartRate === 72, 'L2层级加密解密');

    // 清理密钥
    cryptoEngine.clearKeys();

    console.log('');
  }

  /**
   * 测试存储管理器
   */
  testStorageManager() {
    console.log('--- 测试存储管理器 ---');

    // 初始化
    storageManager.init();

    // 测试保存数据
    const testData = { steps: 5000, heartRate: [65, 72, 78] };
    const saveResult = storageManager.save('test-data', testData, {
      level: 'L1',
      expiryDays: 1
    });
    this.assert(saveResult === true, '数据保存成功');

    // 测试读取数据
    const loaded = storageManager.load('test-data');
    this.assert(loaded.data !== null, '数据读取成功');
    this.assert(loaded.data.steps === 5000, '数据内容正确');
    this.assert(loaded.expired === false, '数据未过期');

    // 测试数据统计
    const stats = storageManager.getStats();
    this.assert(stats.activeCount > 0, '有活跃数据');

    // 测试生命周期信息
    const lifecycle = storageManager.getLifecycleInfo('test-data');
    this.assert(lifecycle !== null, '获取生命周期信息');
    this.assert(lifecycle.remainingDays > 0, '剩余天数大于0');

    // 测试删除数据
    storageManager.delete('test-data');
    const afterDelete = storageManager.load('test-data');
    this.assert(afterDelete.data === null, '数据删除后为null');

    // 测试清理过期数据
    const cleaned = storageManager.cleanup();
    this.assert(typeof cleaned === 'number', '清理返回数字');

    console.log('');
  }

  /**
   * 测试Mock传感器
   */
  testSensorMock() {
    console.log('--- 测试Mock传感器 ---');

    // 测试单个样本生成
    const normalSample = sensorMock.generateSample(POSTURE_TYPES.NORMAL);
    this.assert(typeof normalSample.ax === 'number', '正常样本ax为数字');
    this.assert(typeof normalSample.ay === 'number', '正常样本ay为数字');
    this.assert(typeof normalSample.az === 'number', '正常样本az为数字');

    // 测试不同场景数据生成
    const headDownData = sensorMock.generate(POSTURE_TYPES.HEAD_DOWN, 1000);
    this.assert(headDownData.length > 0, '低头数据生成成功');

    const sittingData = sensorMock.generate(POSTURE_TYPES.SITTING_LONG, 1000);
    this.assert(sittingData.length > 0, '久坐数据生成成功');

    const crossLegsData = sensorMock.generate(POSTURE_TYPES.CROSS_LEGS, 1000);
    this.assert(crossLegsData.length > 0, '跷二郎腿数据生成成功');

    // 测试心率数据生成
    const heartRateData = sensorMock.generateHeartRate(60000);
    this.assert(heartRateData.length > 0, '心率数据生成成功');
    this.assert(heartRateData[0].bpm > 50 && heartRateData[0].bpm < 150, '心率在合理范围');

    // 测试步数数据生成
    const stepsData = sensorMock.generateSteps(60000);
    this.assert(stepsData.length > 0, '步数数据生成成功');

    // 测试GPS数据生成
    const trajectoryData = sensorMock.generateTrajectory(60000);
    this.assert(trajectoryData.length > 0, 'GPS数据生成成功');
    this.assert(trajectoryData[0].lat > 39 && trajectoryData[0].lat < 40, '纬度在合理范围');

    console.log('');
  }

  /**
   * 断言方法
   */
  assert(condition, message) {
    if (condition) {
      this.passed++;
      this.results.push({ passed: true, message });
      console.log(`  ✓ ${message}`);
    } else {
      this.failed++;
      this.results.push({ passed: false, message });
      console.log(`  ✗ ${message}`);
    }
  }

  /**
   * 打印结果
   */
  printResults() {
    console.log('========================================');
    console.log('测试结果');
    console.log('========================================');
    console.log(`通过: ${this.passed}`);
    console.log(`失败: ${this.failed}`);
    console.log(`总计: ${this.passed + this.failed}`);
    console.log(`通过率: ${((this.passed / (this.passed + this.failed)) * 100).toFixed(1)}%`);
    console.log('========================================');
  }

  /**
   * 获取摘要
   */
  getSummary() {
    return {
      passed: this.passed,
      failed: this.failed,
      total: this.passed + this.failed,
      passRate: ((this.passed / (this.passed + this.failed)) * 100).toFixed(1) + '%',
      results: this.results
    };
  }

  /**
   * 重置测试
   */
  reset() {
    this.results = [];
    this.passed = 0;
    this.failed = 0;
  }
}

export default new TestSuite();

